gallery = headband('A CONSENT-FIRST GALLERY','Real stories deserve <em>real permission.</em>','This is an empty before-and-after layout framework, not evidence of client procedures or results. No patient images, invented outcomes or altered comparisons are shown.')+f'''<section class="section wrap"><div class="section-header"><div><p class="eyebrow">BEFORE / AFTER FRAMEWORK</p><h2>Reserved for <em>approved work.</em></h2></div><p>Only verified permission and truthful context can turn these placeholders into a real gallery.</p></div><div class="gallery-grid"><article class="gallery-pair"><div class="pair"><div class="photo-slot"><span>BEFORE</span><strong>Approved photo required</strong></div><div class="photo-slot"><span>AFTER</span><strong>Approved photo required</strong></div></div><h3>Gallery example 01</h3><p>No patient image or procedure outcome is being represented. A real client must document marketing consent.</p></article><article class="gallery-pair"><div class="pair"><div class="photo-slot"><span>BEFORE</span><strong>Approved photo required</strong></div><div class="photo-slot"><span>AFTER</span><strong>Approved photo required</strong></div></div><h3>Gallery example 02</h3><p>For real comparisons, confirm consistent lighting and angles, unaltered photography and relevant disclosures.</p></article></div></section><section class="section sand"><div class="wrap split"><div><p class="eyebrow">ETHICAL PRESENTATION</p><h2>Permission comes <em>first.</em></h2><p>Use only authorized, authentic images with accurate dates, process descriptions and applicable disclosures. Never promise results or imply a single outcome is typical.</p>{btn('Preview a consultation')}</div><div class="information"><h3>Every gallery pair needs</h3><ul><li>Documented, specific marketing/photo consent</li><li>Appropriate patient privacy review</li><li>Comparable lighting, pose and camera conditions</li><li>Correct service, sequence and timeline</li><li>Approved context and truth-in-advertising review</li></ul></div></div></section>'''

consultation = headband('CONSULTATION PREVIEW','A good place <em>to begin.</em>','Select only broad cosmetic interests. Do not submit diagnoses, symptoms, medications, allergies or other sensitive health information.')+f'''<section class="section wrap consult-grid"><aside class="consult-aside"><p class="eyebrow">HOW THIS DEMO WORKS</p><h2>A conversation, <em>not a diagnosis.</em></h2><p>This is a local-only request preview. An actual practice would connect its own booking system and handle health screening in a separate, properly secured process.</p><div class="step"><strong>01</strong><span>Choose an example category and general cosmetic interest.</span></div><div class="step"><strong>02</strong><span>Select a sample provider and preferred date.</span></div><div class="step"><strong>03</strong><span>Enter basic contact details to test browser validation.</span></div><p class="aside-note">No booking, data transfer, medical intake, upload or payment occurs on this website.</p></aside><div class="form-panel"><p class="eyebrow">LOCAL VALIDATION / NOT A BOOKING</p><h2>Consultation interest</h2><p>All values remain in this browser temporarily and are cleared after a successful demo submission.</p><form id="consultation-form" novalidate autocomplete="off"><fieldset><legend>Your interests</legend><div class="form-row"><label>Treatment category *<select name="treatment" required><option value="">Choose category</option><option value="facials">Facials &amp; cosmetic care</option><option value="consult">Skin consultation</option><option value="advanced">Provider-led aesthetics consultation</option><option value="unsure">Not sure yet</option></select></label><label>General cosmetic interest *<select name="interest" required><option value="">Select general topic</option><option value="hydration">Hydration and comfort</option><option value="texture">Appearance of tone / texture</option><option value="routine">Skin-care routine</option><option value="options">Exploring options</option></select></label></div><div class="form-row"><label>Preferred provider *<select name="provider" required><option value="">Choose a preference</option><option value="first">First available (sample only)</option><option value="esthetician">Esthetician role (placeholder)</option><option value="clinician">Clinical provider (unverified sample)</option></select></label><label>Preferred date *<input type="date" name="preferred_date" required><small>Does not check availability or make an appointment.</small></label></div></fieldset><fieldset><legend>Basic contact only</legend><div class="form-row"><label>Full name *<input name="full_name" type="text" minlength="2" maxlength="80" placeholder="Your name" required></label><label>Email *<input name="email" type="email" maxlength="120" placeholder="you@example.com" required></label></div><div class="form-row"><label>Phone *<input name="phone" type="tel" minlength="7" maxlength="25" placeholder="Phone number" required></label><label>Preferred contact *<select name="contact" required><option value="">Choose contact method</option><option value="email">Email</option><option value="call">Phone</option></select></label></div></fieldset><label class="consent"><input type="checkbox" name="demo_consent" required><span>I understand that this fictional demo does not send, store, book, share or process payments. I will not enter medical information.</span></label><button class="btn" type="submit">Validate request preview <span aria-hidden="true">↗</span></button><div id="form-status" class="form-status" role="status" aria-live="polite"></div><p class="fine">There is no form action or backend. The real client chooses a secure vendor and completes a privacy and regulatory review before actual intake.</p></form></div></section>'''

pages=[('', 'Aura & Form | Med Spa & Aesthetics Demo', 'Original fictional med spa template with sample facials, provider credential placeholders and local-only consultation preview.', 'Home', home),('services','Services | Aura & Form Med Spa Demo','Illustrative facial and cosmetic skin service menu with sample prices and consultation-led aesthetic topics.','Services',services),('team','Providers & Policies | Aura & Form Demo','Sample provider role bios, credential and oversight requirements and booking policy placeholders.','The Team',team),('gallery','Consent-First Gallery | Aura & Form Demo','Empty before-and-after gallery framework with consent and photography requirements, without claimed results.','Gallery',gallery),('consultation','Consultation Request Preview | Aura & Form','A safe browser-only form for general cosmetic interests and basic contact details without medical data or booking.','Consultation',consultation)]

for slug,title,desc,active,body in pages:
    folder=ROOT / slug if slug else ROOT
    folder.mkdir(parents=True,exist_ok=True)
    (folder/'index.html').write_text(layout(slug,title,desc,active,body),encoding='utf-8')
print('Generated',len(pages),'HTML routes')
